/* AIVIC_FUNCTION_BUNDLE_START owner=detectMissingReportsAcrossYearBoundary exports=detectMissingReportsAcrossYearBoundary */
const __aivicBundle_28_detectMissingReportsAcrossYearBoundary = (() => {
  function detectMissingReportsAcrossYearBoundary(input: {
    reference_date: Date;
    target_date: Date;
    employees: Array<{
      employee_id: string;
      employee_name: string;
      submission_date: Date | null;
      is_submitted: boolean;
    }>;
    fiscal_year_boundary: {
      prev_year_final_day: Date;
      new_year_first_day: Date;
    };
  }): {
    target_date: Date;
    missing_report_count: number;
    missing_report_employees: Array<{
      employee_id: string;
      employee_name: string;
    }>;
    display_message: string;
  } {
    if (input["reference_date"] === undefined || input["reference_date"] === null) { throw new Error("reference_date is required"); }
    if (
      input.reference_date === undefined ||
      input.reference_date === null ||
      String(input.reference_date).trim() === ""
    ) {
      throw new Error("reference_date is required");
    }
  
    const {
      target_date,
      employees,
      fiscal_year_boundary: { prev_year_final_day },
    } = input;
  
    // 前年度最終日に報告を送信した部員のIDを特定
    const submittedOnPrevYearFinalDay = new Set<string>();
    for (const emp of employees) {
      if (
        emp.is_submitted &&
        emp.submission_date &&
        emp.submission_date.getTime() === prev_year_final_day.getTime()
      ) {
        submittedOnPrevYearFinalDay.add(emp.employee_id);
      }
    }
  
    // 前年度最終日に報告していない部員を抽出
    const missingEmployees = employees.filter((emp) => {
      return !submittedOnPrevYearFinalDay.has(emp.employee_id);
    });
  
    const missing_report_employees = missingEmployees.map((emp) => ({
      employee_id: emp.employee_id,
      employee_name: emp.employee_name,
    }));
  
    const missing_report_count = missing_report_employees.length;
  
    // 表示メッセージを生成（年月日 件数 報告漏れ部員）
    const year = target_date.getUTCFullYear();
    const month = target_date.getUTCMonth() + 1;
    const day = target_date.getUTCDate();
    const display_message = `${year}年${month}月${day}日 ${missing_report_count}名 報告漏れ部員`;
  
    return {
      target_date,
      missing_report_count,
      missing_report_employees,
      display_message,
    };
  }
  return { detectMissingReportsAcrossYearBoundary };
})();
export const detectMissingReportsAcrossYearBoundary = __aivicBundle_28_detectMissingReportsAcrossYearBoundary.detectMissingReportsAcrossYearBoundary;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectMissingReportsAcrossYearBoundary */

