const __aivicBundle_50_validateSenderEmailFormat = (() => {
  function validateSenderEmailFormat(email: string): { isValid: boolean; error?: string } {
    // RFC 5322 simplified validation for email format
    // Check for basic structural requirements
    
    if (typeof email !== 'string') {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    const trimmedEmail = email.trim();
  
    // Check if email is empty
    if (trimmedEmail.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for exactly one @ symbol
    const atCount = (trimmedEmail.match(/@/g) || []).length;
    if (atCount !== 1) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    const [localPart, domain] = trimmedEmail.split('@');
  
    // Validate local part (before @)
    if (!localPart || localPart.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for spaces in local part
    if (localPart.includes(' ')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Validate domain part (after @)
    if (!domain || domain.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Domain must contain at least one dot and have valid structure
    if (!domain.includes('.')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for invalid domain patterns
    if (domain.startsWith('.') || domain.endsWith('.')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for consecutive dots
    if (domain.includes('..')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for spaces in domain
    if (domain.includes(' ')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Validate domain has valid TLD (at least 2 characters after last dot)
    const domainParts = domain.split('.');
    const tld = domainParts[domainParts.length - 1];
    if (!tld || tld.length < 2) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    return {
      isValid: true,
    };
  }
  return { validateSenderEmailFormat };
})();
export const validateSenderEmailFormat = __aivicBundle_50_validateSenderEmailFormat.validateSenderEmailFormat;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateSenderEmailFormat */

